// Ships a baseline profile with an app. Fire TV has no Play Store to deliver
// one, so profileinstaller compiles it on the device after install.
import androidx.baselineprofile.gradle.consumer.BaselineProfileConsumerExtension

plugins {
    id("androidx.baselineprofile")
}

val libs = the<VersionCatalogsExtension>().named("libs")

configure<BaselineProfileConsumerExtension> {
    // One profile for every channel, kept in src/main and regenerated by hand.
    mergeIntoMain = true
    saveInSrc = true
    automaticGenerationDuringBuild = false
}

dependencies {
    "implementation"(libs.findLibrary("profileinstaller").get())
}
